const b = $input.first().json.body || $input.first().json;

const qid = Number(b.question_id);
if (!qid) throw new Error('Не указан question_id');

const action = String(b.action || '').toLowerCase();
if (['approve', 'reject', 'edit'].indexOf(action) === -1) {
  throw new Error('action должен быть approve, reject или edit');
}

function esc(v) {
  return String(v || '').trim().replace(/'/g, "''");
}

const qText = esc(b.question_text);
const qRef  = esc(b.reference_answer);

if (action === 'edit' && qText.length < 15) {
  throw new Error('При редактировании нужен текст вопроса не короче 15 символов');
}

let status = 'approved';
if (action === 'reject') status = 'rejected';

return [{ json: {
  question_id:      qid,
  or_id:            Number(b.or_id) || null,
  action:           action,
  status:           status,
  question_text:    qText,
  reference_answer: qRef,
  comment:          esc(b.comment),
  has_text:         qText.length > 0,
  has_ref:          qRef.length > 0
}}];
